# graph with diagonal shortcuts suppressed when a 4-neighbor bridges the corner
pts=[tuple(x) for x in np.argwhere(s)] # y,x
S=set(pts)
adj={p:[] for p in pts}
for y,x in pts:
 for dy in [-1,0,1]:
  for dx in [-1,0,1]:
   if not (dy or dx):continue
   q=(y+dy,x+dx)
   if q not in S:continue
   if dy and dx and ((y+dy,x) in S or (y,x+dx) in S):continue
   adj[(y,x)].append(q)
deg2={p:len(v) for p,v in adj.items()}
print('suppressed degree hist', {i:sum(d==i for d in deg2.values()) for i in range(9)})
nodepix={p for p,d in deg2.items() if d!=2}
# group adjacent node pixels into junction clusters under same adjacency
clusters=[]
while nodepix:
 st=[nodepix.pop()];cl=[]
 while st:
  p=st.pop();cl.append(p)
  for q in adj[p]:
   if q in nodepix:nodepix.remove(q);st.append(q)
 clusters.append(cl)
# endpoint singleton vs branch cluster
print('node clusters',len(clusters))
branch=[]
for cl in clusters:
 if len(cl)>1 or any(deg2[p]>=3 for p in cl):
  ys=np.array([p[0] for p in cl]);xs=np.array([p[1] for p in cl])
  branch.append((len(cl),(float(xs.mean()),float(ys.mean())),(int(xs.min()),int(ys.min()),int(xs.max()),int(ys.max())),max(deg2[p] for p in cl)))
print('branches',sorted(branch,key=lambda z:z[1][1]))
# use branch cluster and endpoints as graph nodes, trace each edge between clusters
cid={p:i for i,cl in enumerate(clusters) for p in cl}
edge_out=[];visited=set()
for i,cl in enumerate(clusters):
 for p in cl:
  for q in adj[p]:
   j=cid[q]
   if i==j:continue
   ekey=tuple(sorted((p,q)))
   if ekey in visited:continue
   path=[p,q];visited.add(ekey);prev=p;cur=q
   while cid[cur]==j and len(clusters[j])==1 and deg2[cur]==2:
    # won't happen: single node cluster is endpoint/branch with !=2
    break
   # Continue from q through deg2 pixels until reach any node cluster
   while cid[cur] not in (i,) and deg2[cur]==2:
    ns=[z for z in adj[cur] if z!=prev]
    if not ns:break
    nxt=ns[0];visited.add(tuple(sorted((cur,nxt))));prev,cur=cur,nxt;path.append(cur)
   jj=cid[cur]
   edge_out.append((i,jj,path))
print('edges',len(edge_out))
for i,j,path in edge_out:
 a=np.array(path); print(i,'->',j,'n',len(path),'xy',tuple(np.round(a[:,::-1].mean(0),1)),'end',tuple(a[0,::-1]),tuple(a[-1,::-1]))
